const LANGS = { de, en };

export function translator(hass) {
  const lang = (hass?.locale?.language || hass?.language || "en").split("-")[0];
  const dict = LANGS[lang] || en;
  return (key, vars = {}) => {
    // one of something: a "_one" variant, when the language has it
    const count = vars.rows ?? vars.n;
    // counts often arrive formatted ("1", "1.234"): compare the digits
    const one = count !== undefined && String(count).replace(/\D/g, "") === "1" ? dict[`${key}_one`] ?? en[`${key}_one`] : undefined;
    let text = one ?? dict[key] ?? en[key] ?? key;
    for (const [k, v] of Object.entries(vars)) text = text.replaceAll(`{${k}}`, String(v));
    return text;
  };
}

export function locale(hass) {
  return hass?.locale?.language || hass?.language || "en";
}
